import{_ as e}from"./chunks/rover_attitude_controller.BAaBvnaH.js";import{_ as r,c as a,al as o,o as i}from"./chunks/framework.D3pXwl8O.js";const m=JSON.parse('{"title":"Attitude Tuning","description":"","frontmatter":{},"headers":[],"relativePath":"en/config_rover/attitude_tuning.md","filePath":"en/config_rover/attitude_tuning.md"}'),n={name:"en/config_rover/attitude_tuning.md"};function l(d,t,s,c,u,h){return i(),a("div",null,t[0]||(t[0]=[o('<h1 id="attitude-tuning" tabindex="-1">Attitude Tuning <a class="header-anchor" href="#attitude-tuning" aria-label="Permalink to &quot;Attitude Tuning&quot;">​</a></h1><p>Attitude tuning is required to use <a href="./../flight_modes_rover/manual.html#stabilized-mode">Stabilized mode</a> and all later modes.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The <a href="./rate_tuning.html">rate tuning</a> must&#39;ve already been completed before this step!</p></div><p>Configure the following <a href="./../advanced_config/parameters.html">parameters</a> in QGroundControl:</p><ol><li><p><a href="#RO_YAW_P">RO_YAW_P</a> [-]: Proportional gain for the closed loop yaw controller.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In stabilized mode the closed loop yaw control is only active when driving a straight line (no yaw rate input). To tune it start with a value of 1 for <a href="#RO_YAW_P">RO_YAW_P</a>. Put the rover into stabilized mode and move the left stick of your controller up to drive forwards. Disarm the rover and from the flight log plot the <code>measured_yaw</code> and the <code>adjusted_yaw_setpoint</code> from the <a href="./../msg_docs/RoverAttitudeStatus.html">RoverAttitudeStatus</a> message over each other. Increase/Decrease the parameter until you are satisfied with the setpoint tracking. If you observe a steady state error in the yaw setpoint increase the the integrator of the rate controller: <a href="./../advanced_config/parameter_reference.html#RO_YAW_RATE_I">RO_YAW_RATE_I</a> .</p></div></li></ol><p>The rover is now ready to drive in <a href="./../flight_modes_rover/manual.html#stabilized-mode">Stabilized mode</a> and the configuration can be continued with <a href="./velocity_tuning.html">velocity tuning</a>.</p><h2 id="attitude-controller-structure-info-only" tabindex="-1">Attitude Controller Structure (Info Only) <a class="header-anchor" href="#attitude-controller-structure-info-only" aria-label="Permalink to &quot;Attitude Controller Structure (Info Only)&quot;">​</a></h2><p>This section provides additional information for developers and people with experience in control system design.</p><p>The attitude controller uses the following structure:</p><p><img src="'+e+'" alt="Rover Attitude Controller"></p><p>The rate and attitude controllers are cascaded, therefor we only require one integrator in the structure to eliminate steady state errors. We placed the integrator in the rate controller since it can run without the attitude controller but not the other way around.</p><h2 id="parameter-overview" tabindex="-1">Parameter Overview <a class="header-anchor" href="#parameter-overview" aria-label="Permalink to &quot;Parameter Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th><th>Unit</th></tr></thead><tbody><tr><td><a id="RO_YAW_P"></a><a href="./../advanced_config/parameter_reference.html#RO_YAW_P">RO_YAW_P</a></td><td>Proportional gain for yaw controller</td><td>-</td></tr></tbody></table>',13)]))}const f=r(n,[["render",l]]);export{m as __pageData,f as default};
